node = { version = "22", lazy = true }
"npm:chalk" = { version = "5.4.1", lazy = true }
' > mise.toml && echo "== env PATH entries ==" && mise env 2>&1 | grep -oE 'PATH=[^ ]*' | tr ':' '
' | grep -i 'mise\|shim\|chalk\|node' | head -10; echo "== shims dir ==" && ls ~/.local/share/mise/shims 2>/dev/null; ls /tmp/lazy-test-data/shims 2>/dev/null; echo "== which chalk (no install trigger, dry) ==" && mise which chalk 2>&1 | tail -2
